<?php $days=[1=>'Lundi',2=>'Mardi',3=>'Mercredi',4=>'Jeudi',5=>'Vendredi',6=>'Samedi',7=>'Dimanche']; $byDay=[]; foreach($openingHours as $h){$byDay[(int)$h['day_of_week']]=$h;} ?>
<main class="py-5"><div class="container"><h1 class="h2 text-primary mb-4">Horaires d'ouverture</h1><form method="post" action="/admin/hours" class="card border-0 shadow-sm"><div class="card-body"><?php foreach($days as $day=>$label): $h=$byDay[$day]??['is_open'=>0,'opening_time'=>'','closing_time'=>'']; ?><div class="row g-2 align-items-end mb-3"><div class="col-md-3"><strong><?= $label ?></strong></div><div class="col-md-2"><label class="form-label">Ouvert</label><input class="form-check-input d-block" type="checkbox" name="is_open[<?= $day ?>]" <?= (int)$h['is_open']===1?'checked':'' ?>></div><div class="col-md-3"><label class="form-label">Ouverture</label><input class="form-control" type="time" name="opening_time[<?= $day ?>]" value="<?= $escape(substr((string)$h['opening_time'],0,5)) ?>"></div><div class="col-md-3"><label class="form-label">Fermeture</label><input class="form-control" type="time" name="closing_time[<?= $day ?>]" value="<?= $escape(substr((string)$h['closing_time'],0,5)) ?>"></div></div><?php endforeach; ?><input type="hidden" name="csrf_token" value="<?= $escape($csrfToken) ?>"><button class="btn btn-primary">Enregistrer</button></div></form></div></main>
